<?php require_once 'config/database.php'; require_once 'includes/auth.php'; require_login(); $stmt=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?'); $stmt->execute([(int)($_GET['id']??0),$_SESSION['user']['id']]); $order=$stmt->fetch(); if(!$order) redirect('my_orders.php'); $page_title='Order Success'; include 'includes/header.php'; ?><div class="form-shell"><div class="eyebrow">Thank you</div><h1>Order Placed Successfully!</h1><p class="success">Your kitchen ticket is on its way.</p><div class="notice"><p><strong>Order ID:</strong> #<?= $order['id'] ?></p><p><strong>Total:</strong> ₹<?= number_format($order['total_amount'],2) ?></p><p><strong>Payment:</strong> <?= esc($order['payment_method']) ?></p><p><strong>Delivery address:</strong> <?= esc($order['delivery_address']) ?></p><p><strong>Status:</strong> <?= esc($order['order_status']) ?></p></div><a class="button" href="my_orders.php">View My Orders</a> <a class="button secondary" href="menu.php">Continue Shopping</a></div><?php include 'includes/footer.php'; ?>